<script setup>
import { computed, onMounted, ref } from 'vue'
import { getApiError } from '../../api/client'
import { students, guardians } from '../../api/students'
import { academicYears, classes, streams } from '../../api/schoolStructure'

const rows=ref([]),selected=ref(null),loading=ref(true),saving=ref(false),error=ref(''),notice=ref(''),search=ref(''),status=ref('')
const years=ref([]),classRows=ref([]),streamRows=ref([]),guardianRows=ref([])
const showCreate=ref(false),showEdit=ref(false),showLink=ref(false),showGuardianCreate=ref(false),showGuardianEdit=ref(false),showEnroll=ref(false),showEnrollEdit=ref(false)
const studentForm=ref({admission_number:'',first_name:'',middle_name:'',last_name:'',date_of_birth:'',gender:'unspecified',nationality:'Kenyan',birth_certificate_number:'',admission_date:'',previous_school:'',status:'active',medical_notes:'',emergency_notes:''})
const editStudentForm=ref({})
const linkFormData=ref({guardian_id:'',relationship:'Parent',is_primary:true,is_emergency_contact:true,can_pick_up:true})
const guardianForm=ref({first_name:'',last_name:'',phone:'',alternative_phone:'',email:'',address:'',occupation:'',employer:'',preferred_contact_method:'phone',status:'active'})
const guardianEdit=ref({})
const enrollForm=ref({academic_year_id:'',class_level_id:'',stream_id:'',enrollment_date:new Date().toISOString().slice(0,10),exit_date:'',status:'active',notes:''})
const enrollEdit=ref({})
const fullName=s=>[s?.first_name,s?.middle_name,s?.last_name].filter(Boolean).join(' ')
const flash=m=>{notice.value=m;setTimeout(()=>notice.value='',3000)}
const availableStreams=computed(()=>streamRows.value.filter(s=>!enrollForm.value.class_level_id||s.class_level_id===enrollForm.value.class_level_id))
const editStreams=computed(()=>streamRows.value.filter(s=>!enrollEdit.value.class_level_id||s.class_level_id===enrollEdit.value.class_level_id))

async function load(){loading.value=true;error.value='';try{rows.value=await students.list({search:search.value||undefined,status:status.value||undefined})}catch(e){error.value=getApiError(e)}finally{loading.value=false}}
async function loadOptions(){try{[years.value,classRows.value,streamRows.value,guardianRows.value]=await Promise.all([academicYears.list(),classes.list(),streams.list(),guardians.list()])}catch(e){error.value=getApiError(e)}}
function newStudent(){studentForm.value={admission_number:'',first_name:'',middle_name:'',last_name:'',date_of_birth:'',gender:'unspecified',nationality:'Kenyan',birth_certificate_number:'',admission_date:'',previous_school:'',status:'active',medical_notes:'',emergency_notes:''};showCreate.value=true}
function editStudent(){editStudentForm.value={...selected.value};showEdit.value=true}
async function createStudent(){saving.value=true;try{await students.create(studentForm.value);showCreate.value=false;await load();flash('Student admitted successfully.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
async function saveStudent(){saving.value=true;try{await students.update(selected.value.id,editStudentForm.value);selected.value=await students.get(selected.value.id);showEdit.value=false;await load();flash('Student profile updated.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
async function openStudent(s){try{selected.value=await students.get(s.id)}catch(e){error.value=getApiError(e)}}
function newGuardian(){guardianForm.value={first_name:'',last_name:'',phone:'',alternative_phone:'',email:'',address:'',occupation:'',employer:'',preferred_contact_method:'phone',status:'active'};showGuardianCreate.value=true}
async function createGuardian(){saving.value=true;try{const g=await guardians.create(guardianForm.value);await loadOptions();showGuardianCreate.value=false;linkFormData.value={guardian_id:g.id,relationship:'Parent',is_primary:!selected.value.guardians?.length,is_emergency_contact:true,can_pick_up:true};showLink.value=true;flash('Guardian created. Complete the relationship to link them.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
function linkGuardianOpen(){linkFormData.value={guardian_id:'',relationship:'Parent',is_primary:!selected.value?.guardians?.length,is_emergency_contact:true,can_pick_up:true};showLink.value=true}
async function linkGuardian(){saving.value=true;try{await students.linkGuardian(selected.value.id,linkFormData.value);selected.value=await students.get(selected.value.id);await loadOptions();showLink.value=false;flash('Guardian linked.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
function editGuardian(g){guardianEdit.value={...g.guardian,_id:g.guardian_id};showGuardianEdit.value=true}
async function saveGuardian(){saving.value=true;try{const id=guardianEdit.value._id;const payload={...guardianEdit.value};delete payload._id;await guardians.update(id,payload);selected.value=await students.get(selected.value.id);await loadOptions();showGuardianEdit.value=false;flash('Guardian updated.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
async function unlinkGuardian(g){if(!confirm(`Remove ${fullName(g.guardian)} from this student?`))return;try{await students.unlinkGuardian(selected.value.id,g.guardian_id);selected.value=await students.get(selected.value.id);flash('Guardian removed.')}catch(e){error.value=getApiError(e)}}
function newEnrollment(){enrollForm.value={academic_year_id:years.value.find(y=>y.is_current)?.id||years.value[0]?.id||'',class_level_id:'',stream_id:'',enrollment_date:new Date().toISOString().slice(0,10),exit_date:'',status:'active',notes:''};showEnroll.value=true}
function editEnrollment(e){enrollEdit.value={...e,_id:e.id,stream_id:e.stream_id||'',exit_date:e.exit_date||'',notes:e.notes||''};showEnrollEdit.value=true}
async function createEnrollment(){saving.value=true;try{await students.enroll(selected.value.id,{...enrollForm.value,stream_id:enrollForm.value.stream_id||null,exit_date:enrollForm.value.exit_date||null});selected.value=await students.get(selected.value.id);showEnroll.value=false;flash('Enrollment saved.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
async function saveEnrollment(){saving.value=true;try{const id=enrollEdit.value._id;const payload={...enrollEdit.value};delete payload._id;delete payload.academic_year_name;delete payload.class_name;delete payload.stream_name;payload.stream_id=payload.stream_id||null;payload.exit_date=payload.exit_date||null;await students.updateEnrollment(selected.value.id,id,payload);selected.value=await students.get(selected.value.id);showEnrollEdit.value=false;flash('Enrollment updated.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
onMounted(()=>Promise.all([load(),loadOptions()]))
</script>
<template><div class="students-page"><div class="page-title-row"><div><div class="eyebrow">STUDENT MANAGEMENT</div><h1>Students</h1><p>Admissions, student profiles, guardians and enrollment history.</p></div><button class="btn btn-primary" @click="newStudent"><i class="bi bi-person-plus me-2"></i>Add student</button></div><div v-if="notice" class="alert alert-success border-0 shadow-sm">{{notice}}</div><div v-if="error" class="alert alert-danger border-0 shadow-sm">{{error}}</div><section class="dashboard-card mb-4"><div class="student-toolbar"><div class="search-box"><i class="bi bi-search"></i><input v-model="search" @keyup.enter="load" placeholder="Search admission number or name..." /></div><select v-model="status" class="form-select" @change="load"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option><option value="graduated">Graduated</option><option value="transferred">Transferred</option><option value="withdrawn">Withdrawn</option></select><button class="btn btn-light" @click="load"><i class="bi bi-arrow-clockwise"></i></button></div></section><div class="row g-4"><div :class="selected?'col-xl-7':'col-12'"><section class="dashboard-card"><div class="card-heading"><div><h2>Student register</h2><p>{{rows.length}} student{{rows.length===1?'':'s'}} shown</p></div></div><div v-if="loading" class="py-5 text-center"><span class="spinner-border text-primary"></span></div><div v-else-if="!rows.length" class="empty-state"><i class="bi bi-people"></i><h3>No students yet</h3><p>Start by admitting your first student.</p><button class="btn btn-primary" @click="newStudent">Add first student</button></div><div v-else class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Admission</th><th>Student</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td class="fw-semibold">{{s.admission_number}}</td><td><button class="student-link" @click="openStudent(s)">{{fullName(s)}}</button></td><td><span class="status-pill" :class="s.status">{{s.status}}</span></td><td><button class="btn btn-sm btn-outline-primary" @click="openStudent(s)"><i class="bi bi-pencil-square"></i></button></td></tr></tbody></table></div></section></div><div v-if="selected" class="col-xl-5"><section class="dashboard-card student-detail-card"><div class="detail-head"><div class="student-avatar">{{selected.first_name?.[0]}}{{selected.last_name?.[0]}}</div><div><div class="eyebrow">{{selected.admission_number}}</div><h2>{{fullName(selected)}}</h2><span class="status-pill" :class="selected.status">{{selected.status}}</span></div><button class="btn btn-sm btn-light ms-auto" @click="selected=null"><i class="bi bi-x-lg"></i></button></div><div class="detail-actions"><button class="btn btn-outline-primary btn-sm" @click="editStudent"><i class="bi bi-pencil me-1"></i>Edit profile</button><button class="btn btn-primary btn-sm" @click="newEnrollment"><i class="bi bi-mortarboard me-1"></i>Enroll</button></div><div class="detail-section"><h3>Profile</h3><div class="detail-grid"><div><small>Date of birth</small><strong>{{selected.date_of_birth||'Not provided'}}</strong></div><div><small>Gender</small><strong class="text-capitalize">{{selected.gender}}</strong></div><div><small>Admission date</small><strong>{{selected.admission_date||'Not provided'}}</strong></div><div><small>Nationality</small><strong>{{selected.nationality||'Not provided'}}</strong></div></div></div><div class="detail-section"><div class="section-title"><h3>Guardians</h3><div><button class="btn btn-link btn-sm" @click="linkGuardianOpen">Link</button><button class="btn btn-link btn-sm" @click="newGuardian">New</button></div></div><div v-if="!selected.guardians?.length" class="mini-empty">No guardians linked.</div><div v-for="g in selected.guardians" :key="g.id" class="related-row"><div class="mini-avatar">{{g.guardian?.first_name?.[0]}}{{g.guardian?.last_name?.[0]}}</div><div><strong>{{fullName(g.guardian)}}</strong><small>{{g.relationship}}<span v-if="g.is_primary"> · Primary</span></small></div><button class="btn btn-sm btn-light ms-1" @click="editGuardian(g)"><i class="bi bi-pencil"></i></button><button class="btn btn-sm btn-light ms-auto" @click="unlinkGuardian(g)"><i class="bi bi-x"></i></button></div></div><div class="detail-section"><div class="section-title"><h3>Enrollment history</h3><button class="btn btn-link btn-sm" @click="newEnrollment">Add</button></div><div v-if="!selected.enrollments?.length" class="mini-empty">No enrollment history.</div><div v-for="e in selected.enrollments" :key="e.id" class="history-row"><div><strong>{{e.academic_year_name}}</strong><small>{{e.class_name}}<span v-if="e.stream_name"> · {{e.stream_name}}</span></small></div><span class="status-pill" :class="e.status">{{e.status}}</span><button class="btn btn-sm btn-light ms-2" @click="editEnrollment(e)"><i class="bi bi-pencil"></i></button></div></div></section></div></div>
<div v-if="showCreate" class="modal-backdrop-custom"><div class="modal-card modal-wide"><div class="modal-head"><div><h2>Admit student</h2><p>Create the student's master profile.</p></div><button class="btn btn-light" @click="showCreate=false"><i class="bi bi-x-lg"></i></button></div><div class="row g-3"><div class="col-md-4"><label>Admission number *</label><input v-model="studentForm.admission_number" class="form-control"></div><div class="col-md-4"><label>First name *</label><input v-model="studentForm.first_name" class="form-control"></div><div class="col-md-4"><label>Last name *</label><input v-model="studentForm.last_name" class="form-control"></div><div class="col-md-6"><label>Middle name</label><input v-model="studentForm.middle_name" class="form-control"></div><div class="col-md-3"><label>Date of birth</label><input v-model="studentForm.date_of_birth" type="date" class="form-control"></div><div class="col-md-3"><label>Gender</label><select v-model="studentForm.gender" class="form-select"><option value="unspecified">Unspecified</option><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option></select></div><div class="col-md-4"><label>Nationality</label><input v-model="studentForm.nationality" class="form-control"></div><div class="col-md-4"><label>Birth certificate no.</label><input v-model="studentForm.birth_certificate_number" class="form-control"></div><div class="col-md-4"><label>Admission date</label><input v-model="studentForm.admission_date" type="date" class="form-control"></div><div class="col-md-6"><label>Previous school</label><input v-model="studentForm.previous_school" class="form-control"></div><div class="col-12"><label>Medical notes</label><textarea v-model="studentForm.medical_notes" class="form-control" rows="2"></textarea></div><div class="col-12"><label>Emergency notes</label><textarea v-model="studentForm.emergency_notes" class="form-control" rows="2"></textarea></div></div><div class="modal-actions"><button class="btn btn-light" @click="showCreate=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!studentForm.admission_number||!studentForm.first_name||!studentForm.last_name" @click="createStudent">{{saving?'Saving...':'Admit student'}}</button></div></div></div>
<div v-if="showEdit" class="modal-backdrop-custom"><div class="modal-card modal-wide"><div class="modal-head"><div><h2>Edit student</h2><p>Update the student's master profile.</p></div><button class="btn btn-light" @click="showEdit=false"><i class="bi bi-x-lg"></i></button></div><div class="row g-3"><div class="col-md-4"><label>Admission number</label><input v-model="editStudentForm.admission_number" class="form-control" disabled></div><div class="col-md-4"><label>First name *</label><input v-model="editStudentForm.first_name" class="form-control"></div><div class="col-md-4"><label>Last name *</label><input v-model="editStudentForm.last_name" class="form-control"></div><div class="col-md-6"><label>Middle name</label><input v-model="editStudentForm.middle_name" class="form-control"></div><div class="col-md-3"><label>Date of birth</label><input v-model="editStudentForm.date_of_birth" type="date" class="form-control"></div><div class="col-md-3"><label>Gender</label><select v-model="editStudentForm.gender" class="form-select"><option value="unspecified">Unspecified</option><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option></select></div><div class="col-md-4"><label>Nationality</label><input v-model="editStudentForm.nationality" class="form-control"></div><div class="col-md-4"><label>Birth certificate no.</label><input v-model="editStudentForm.birth_certificate_number" class="form-control"></div><div class="col-md-4"><label>Admission date</label><input v-model="editStudentForm.admission_date" type="date" class="form-control"></div><div class="col-md-4"><label>Status</label><select v-model="editStudentForm.status" class="form-select"><option value="active">Active</option><option value="inactive">Inactive</option><option value="graduated">Graduated</option><option value="transferred">Transferred</option><option value="withdrawn">Withdrawn</option></select></div><div class="col-md-8"><label>Previous school</label><input v-model="editStudentForm.previous_school" class="form-control"></div><div class="col-12"><label>Medical notes</label><textarea v-model="editStudentForm.medical_notes" class="form-control" rows="2"></textarea></div><div class="col-12"><label>Emergency notes</label><textarea v-model="editStudentForm.emergency_notes" class="form-control" rows="2"></textarea></div></div><div class="modal-actions"><button class="btn btn-light" @click="showEdit=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!editStudentForm.first_name||!editStudentForm.last_name" @click="saveStudent">{{saving?'Updating...':'Update student'}}</button></div></div></div>
<div v-if="showGuardianCreate" class="modal-backdrop-custom"><div class="modal-card"><div class="modal-head"><div><h2>New guardian</h2><p>Create a guardian profile before linking them.</p></div><button class="btn btn-light" @click="showGuardianCreate=false"><i class="bi bi-x-lg"></i></button></div><div class="row g-3"><div class="col-6"><label>First name *</label><input v-model="guardianForm.first_name" class="form-control"></div><div class="col-6"><label>Last name *</label><input v-model="guardianForm.last_name" class="form-control"></div><div class="col-6"><label>Phone</label><input v-model="guardianForm.phone" class="form-control"></div><div class="col-6"><label>Alternative phone</label><input v-model="guardianForm.alternative_phone" class="form-control"></div><div class="col-12"><label>Email</label><input v-model="guardianForm.email" type="email" class="form-control"></div><div class="col-12"><label>Address</label><input v-model="guardianForm.address" class="form-control"></div><div class="col-6"><label>Occupation</label><input v-model="guardianForm.occupation" class="form-control"></div><div class="col-6"><label>Employer</label><input v-model="guardianForm.employer" class="form-control"></div><div class="col-12"><label>Preferred contact</label><select v-model="guardianForm.preferred_contact_method" class="form-select"><option value="phone">Phone</option><option value="sms">SMS</option><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="any">Any</option></select></div></div><div class="modal-actions"><button class="btn btn-light" @click="showGuardianCreate=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!guardianForm.first_name||!guardianForm.last_name" @click="createGuardian">{{saving?'Saving...':'Create guardian'}}</button></div></div></div>
<div v-if="showGuardianEdit" class="modal-backdrop-custom"><div class="modal-card"><div class="modal-head"><div><h2>Edit guardian</h2><p>Update guardian contact details.</p></div><button class="btn btn-light" @click="showGuardianEdit=false"><i class="bi bi-x-lg"></i></button></div><div class="row g-3"><div class="col-6"><label>First name *</label><input v-model="guardianEdit.first_name" class="form-control"></div><div class="col-6"><label>Last name *</label><input v-model="guardianEdit.last_name" class="form-control"></div><div class="col-6"><label>Phone</label><input v-model="guardianEdit.phone" class="form-control"></div><div class="col-6"><label>Alternative phone</label><input v-model="guardianEdit.alternative_phone" class="form-control"></div><div class="col-12"><label>Email</label><input v-model="guardianEdit.email" type="email" class="form-control"></div><div class="col-12"><label>Address</label><input v-model="guardianEdit.address" class="form-control"></div><div class="col-6"><label>Occupation</label><input v-model="guardianEdit.occupation" class="form-control"></div><div class="col-6"><label>Employer</label><input v-model="guardianEdit.employer" class="form-control"></div><div class="col-6"><label>Preferred contact</label><select v-model="guardianEdit.preferred_contact_method" class="form-select"><option value="phone">Phone</option><option value="sms">SMS</option><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="any">Any</option></select></div><div class="col-6"><label>Status</label><select v-model="guardianEdit.status" class="form-select"><option value="active">Active</option><option value="inactive">Inactive</option></select></div></div><div class="modal-actions"><button class="btn btn-light" @click="showGuardianEdit=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!guardianEdit.first_name||!guardianEdit.last_name" @click="saveGuardian">{{saving?'Updating...':'Update guardian'}}</button></div></div></div>
<div v-if="showLink" class="modal-backdrop-custom"><div class="modal-card"><div class="modal-head"><div><h2>Link guardian</h2><p>Connect a guardian to {{fullName(selected)}}.</p></div><button class="btn btn-light" @click="showLink=false"><i class="bi bi-x-lg"></i></button></div><label>Guardian *</label><select v-model="linkFormData.guardian_id" class="form-select mb-3"><option value="">Select guardian</option><option v-for="g in guardianRows" :key="g.id" :value="g.id">{{fullName(g)}}{{g.phone?' · '+g.phone:''}}</option></select><label>Relationship *</label><input v-model="linkFormData.relationship" class="form-control mb-3"><div class="form-check mb-2"><input v-model="linkFormData.is_primary" class="form-check-input" type="checkbox" id="student-primary"><label for="student-primary">Primary guardian</label></div><div class="form-check mb-2"><input v-model="linkFormData.is_emergency_contact" class="form-check-input" type="checkbox" id="student-emergency"><label for="student-emergency">Emergency contact</label></div><div class="form-check mb-4"><input v-model="linkFormData.can_pick_up" class="form-check-input" type="checkbox" id="student-pickup"><label for="student-pickup">Can pick up student</label></div><div class="modal-actions"><button class="btn btn-light" @click="showLink=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!linkFormData.guardian_id" @click="linkGuardian">Link guardian</button></div></div></div>
<div v-if="showEnroll" class="modal-backdrop-custom"><div class="modal-card"><div class="modal-head"><div><h2>Enroll student</h2><p>Add an academic-year placement.</p></div><button class="btn btn-light" @click="showEnroll=false"><i class="bi bi-x-lg"></i></button></div><label>Academic year *</label><select v-model="enrollForm.academic_year_id" class="form-select mb-3"><option value="">Select year</option><option v-for="y in years" :key="y.id" :value="y.id">{{y.name}}</option></select><label>Class *</label><select v-model="enrollForm.class_level_id" class="form-select mb-3"><option value="">Select class</option><option v-for="c in classRows" :key="c.id" :value="c.id">{{c.name}}</option></select><label>Stream</label><select v-model="enrollForm.stream_id" class="form-select mb-3"><option value="">No stream</option><option v-for="s in availableStreams" :key="s.id" :value="s.id">{{s.name}}</option></select><div class="row g-3 mb-3"><div class="col-6"><label>Enrollment date *</label><input v-model="enrollForm.enrollment_date" type="date" class="form-control"></div><div class="col-6"><label>Status</label><select v-model="enrollForm.status" class="form-select"><option value="active">Active</option><option value="completed">Completed</option><option value="withdrawn">Withdrawn</option></select></div></div><label>Notes</label><textarea v-model="enrollForm.notes" class="form-control mb-4" rows="2"></textarea><div class="modal-actions"><button class="btn btn-light" @click="showEnroll=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!enrollForm.academic_year_id||!enrollForm.class_level_id" @click="createEnrollment">Save enrollment</button></div></div></div>
<div v-if="showEnrollEdit" class="modal-backdrop-custom"><div class="modal-card"><div class="modal-head"><div><h2>Edit enrollment</h2><p>Update the academic-year placement.</p></div><button class="btn btn-light" @click="showEnrollEdit=false"><i class="bi bi-x-lg"></i></button></div><label>Academic year *</label><select v-model="enrollEdit.academic_year_id" class="form-select mb-3"><option v-for="y in years" :key="y.id" :value="y.id">{{y.name}}</option></select><label>Class *</label><select v-model="enrollEdit.class_level_id" class="form-select mb-3"><option v-for="c in classRows" :key="c.id" :value="c.id">{{c.name}}</option></select><label>Stream</label><select v-model="enrollEdit.stream_id" class="form-select mb-3"><option value="">No stream</option><option v-for="s in editStreams" :key="s.id" :value="s.id">{{s.name}}</option></select><div class="row g-3 mb-3"><div class="col-6"><label>Enrollment date *</label><input v-model="enrollEdit.enrollment_date" type="date" class="form-control"></div><div class="col-6"><label>Status</label><select v-model="enrollEdit.status" class="form-select"><option value="active">Active</option><option value="completed">Completed</option><option value="withdrawn">Withdrawn</option></select></div></div><label>Exit date</label><input v-model="enrollEdit.exit_date" type="date" class="form-control mb-3"><label>Notes</label><textarea v-model="enrollEdit.notes" class="form-control mb-4" rows="2"></textarea><div class="modal-actions"><button class="btn btn-light" @click="showEnrollEdit=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!enrollEdit.academic_year_id||!enrollEdit.class_level_id" @click="saveEnrollment">{{saving?'Updating...':'Update enrollment'}}</button></div></div></div>
</div></template>
